const requestData=[];function sendCreatorRequest(i){let c=creators[i];showModal(`<div class="auth-head"><span class="auth-icon">✦</span><h2>Send Request to ${c.name}</h2><p>AI match ${c.match}% · Authenticity ${c.auth}%</p></div><form id="reqForm"><label>Campaign</label><select><option>Summer Glow</option><option>Product Launch</option></select><label>Message</label><textarea rows="5" required placeholder="Explain the campaign and deliverables..."></textarea><button class="btn primary wide">Send Request</button></form>`);q('#reqForm').onsubmit=e=>{e.preventDefault();requestData.push([c.name,'Brand → Creator','Pending']);renderRequests();closeModal();toast('Collaboration request sent')}}
function sendBrandPitch(i){let b=brands[i];showModal(`<div class="auth-head"><span class="auth-icon">✦</span><h2>Pitch ${b.name}</h2><p>${b.match}% creator-brand match</p></div><form id="pitchForm"><label>Your pitch</label><textarea rows="5" required placeholder="Why are you a strong fit for this campaign?"></textarea><label>Your quote</label><input placeholder="₹ Amount" required><button class="btn primary wide">Send Pitch</button></form>`);q('#pitchForm').onsubmit=e=>{e.preventDefault();requestData.push([b.name,'Creator → Brand','Pending']);renderRequests();closeModal();toast('Pitch sent to brand')}}
