function normalizeProfile(provider,p){
 return {provider,display_name:p.display_name||p.name||p.username||'Connected creator',username:p.username||'',bio_description:p.bio_description||p.biography||p.about||'',avatar_url:p.avatar_url||p.profile_picture_url||p.picture?.data?.url||creators[0].img,profile_deep_link:p.profile_deep_link||p.website||'',follower_count:Number(p.follower_count||p.followers_count||p.subscriber_count||0),following_count:Number(p.following_count||p.follows_count||0),video_count:Number(p.video_count||p.media_count||0),view_count:Number(p.view_count||p.avg_views||0),likes_count:Number(p.likes_count||0),engagement_rate:Number(p.engagement_rate||0),recent_media:p.recent_media||[],page:p.page,note:p.note};
}
function authenticity(p){
 const followers=Math.max(p.follower_count,1), recent=p.recent_media||[];
 const avgInteractions=recent.length?recent.reduce((n,x)=>n+Number(x.like_count||0)+Number(x.comments_count||0),0)/recent.length:0;
 const estimatedEngagement=p.engagement_rate||((avgInteractions/followers)*100)||(p.view_count?Math.min(12,p.view_count/followers*8):3.5);
 const engagementScore=Math.min(100,estimatedEngagement*14);
 const consistency=Math.min(100,p.video_count*1.8);
 const completeness=[p.display_name,p.bio_description,p.avatar_url,p.follower_count].filter(Boolean).length*25;
 const reach=p.view_count?Math.min(100,(p.view_count/followers)*120):65;
 return Math.max(35,Math.min(99,Math.round(engagementScore*.35+reach*.25+consistency*.20+completeness*.20)));
}
function saveSocial(){localStorage.setItem('collabaiSocialProfiles',JSON.stringify(socialData));renderProviders();renderUnified()}
function providerCard(x){const p=socialData[x.id],score=p?authenticity(p):null;return `<article class="panel provider-card ${p?'provider-connected':''}"><div class="provider-title"><span class="provider-icon ${x.id}">${x.icon}</span><div><h3>${x.name}</h3><p>${x.subtitle}</p></div>${p?'<span class="connected-pill">Connected</span>':''}</div>${p?`<div class="mini-social"><img src="${p.avatar_url}" alt=""><div><b>${p.display_name}</b><span>${p.follower_count.toLocaleString()} followers</span></div><strong>${score}%<small>AI score</small></strong></div>`:`<p class="muted">Securely import the profile and statistics allowed by ${x.name}.</p>`}<div class="provider-actions">${p?`<button class="btn primary" onclick="refreshSocial('${x.id}')">Refresh</button><button class="btn" onclick="disconnectSocial('${x.id}')">Disconnect</button>`:`<button class="btn primary" onclick="connectSocial('${x.id}')">Connect ${x.name}</button><button class="btn" onclick="demoSocial('${x.id}')">Try Demo</button>`}</div></article>`}
function renderProviders(){const el=q('#providerGrid');if(el)el.innerHTML=socialProviders.map(providerCard).join('')}
function renderUnified(){const el=q('#unifiedProfile');if(!el)return;const profiles=Object.values(socialData);if(!profiles.length){el.className='instagram-preview empty-preview';el.textContent='Connect or demo at least one platform to build your creator profile.';return}const total=profiles.reduce((n,p)=>n+p.follower_count,0),weighted=Math.round(profiles.reduce((n,p)=>n+authenticity(p),0)/profiles.length);el.className='instagram-preview';el.innerHTML=`<div class="ig-profile-head"><img src="${profiles[0].avatar_url}" alt=""><div><h3>${profiles[0].display_name}</h3><p>${profiles[0].bio_description||'Connected creator profile'}</p><div class="platform-tags">${profiles.map(p=>`<span>${p.provider}</span>`).join('')}</div></div><strong>${weighted}%<small>Combined score</small></strong></div><div class="ig-stats"><div><b>${total.toLocaleString()}</b><span>Total followers</span></div><div><b>${profiles.length}</b><span>Platforms</span></div><div><b>${profiles.reduce((n,p)=>n+p.video_count,0).toLocaleString()}</b><span>Published items</span></div><div><b>${Math.round(profiles.reduce((n,p)=>n+(p.engagement_rate||0),0)/profiles.length*10)/10||'AI' }%</b><span>Avg. engagement</span></div></div><div class="connected-list">${profiles.map(p=>`<div><span class="provider-icon ${p.provider}">${socialProviders.find(x=>x.id===p.provider)?.icon||'•'}</span><div><b>${p.display_name}</b><small>${p.follower_count.toLocaleString()} followers • ${authenticity(p)}% authenticity</small></div></div>`).join('')}</div>`}
