async function apiAuth(type,role,name,email,password){const endpoint=type==='login'?'/api/auth/login':'/api/auth/signup';const body=type==='login'?{email,password}:{name,email,password,role};const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Authentication failed');localStorage.setItem('collabaiToken',d.token);localStorage.setItem('collabaiRole',d.user.role);return d;}
