 showModal(`<div class="auth-head"><span class="auth-icon">🏢</span><h2>Edit brand profile</h2><p>Changes update brand search immediately.</p></div><form id="brandEditor"><label>Company name</label><input name="companyName" value="${p.companyName||''}"><label>Industry</label><input name="industry" value="${p.industry||''}"><label>Location</label><input name="location" value="${p.location||''}"><label>Website</label><input name="website" value="${p.website||''}"><label>Description</label><textarea name="description">${p.description||''}</textarea><label>Budget range</label><input name="budgetRange" value="${p.budgetRange||''}"><button class="btn primary wide">Save brand</button></form>`);
 setTimeout(()=>{const f=q('#brandEditor');if(f)f.onsubmit=async e=>{e.preventDefault();const rr=await fetch('/api/profile/me',{method:'PUT',headers:apiHeaders(),body:JSON.stringify(Object.fromEntries(new FormData(f)))});const out=await rr.json();if(!rr.ok)return toast(out.error||'Save failed');closeModal();toast('Brand updated dynamically');loadDynamicMarketplace();};},30);
